{"bytes": 382380, "encoding": "PACKLINES1", "lines": [{"text": "#!/bin/bash\n"}, {"text": "# Run on Orchard login. STEP=200 or 544; override SOURCE_1TGZ/SOURCE_SHA256 only together.\n"}, {"text": "set -euo pipefail\n"}, {"text": "umask 077\n"}, {"text": ": \"${STAGE:=/project/community/jjyeung/okh7/813f42db/d}\"\n"}, {"text": ": \"${STEP:=200}\"\n"}, {"text": ": \"${WALLTIME:=04:00:00}\"\n"}, {"text": ": \"${SOURCE_1TGZ:=/project/community/jjyeung/okh7/a15_cot_ap4e8c539166092f0c/1.tgz}\"\n"}, {"text": ": \"${SOURCE_SHA256:=c3187ab9f88b3eb5a7ab1e30a8010e4ef86acb49d6c76e98fd97eec393b4e45a}\"\n"}, {"text": "case \"$STEP\" in 200|544) ;; *) echo 'STEP must be 200 or 544' >&2; exit 1;; esac\n"}, {"text": "test ! -e \"$STAGE\"\n"}, {"text": "mkdir -m 700 \"$STAGE\"\n"}, {"text": "/usr/bin/python3 -B - \"$STAGE\" \"$STEP\" <<'PYASSETS'\n"}, {"text": "import base64,gzip,hashlib,json,sys\n"}, {"text": "from pathlib import Path\n"}, {"text": "stage=Path(sys.argv[1]);step=sys.argv[2]\n"}, {"block": "44675d1ddc62edba04a4e9cee6375b2c653dae6d194c4af6061315c4c955ab60"}, {"text": "for name,spec in assets.items():\n"}, {"text": "    raw=gzip.decompress(base64.b64decode(spec['data']))\n"}, {"text": "    assert hashlib.sha256(raw).hexdigest()==spec['sha256']\n"}, {"text": "    path=stage/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw)\n"}, {"text": "(stage/'binding.json').write_bytes((stage/('bind_D'+step+'.json')).read_bytes())\n"}, {"text": "PYASSETS\n"}, {"text": "/usr/bin/python3 -B \"$STAGE/b.py\" \"$STAGE\" \"$SOURCE_1TGZ\" \"$SOURCE_SHA256\" \"$STAGE/items/dist580.json\" \"$STAGE/binding.json\" --time \"$WALLTIME\"\n"}, {"text": "/usr/bin/python3 -B - \"$STAGE\" <<'PYRESULT'\n"}, {"text": "import json,sys\n"}, {"text": "from pathlib import Path\n"}, {"text": "r=json.loads((Path(sys.argv[1])/'BUILD.json').read_text())['D']\n"}, {"text": "print('token='+r['token'])\n"}, {"text": "print('delivery_dir='+r['delivery_dir'])\n"}, {"text": "print('sha256='+r['delivery_sha256'])\n"}, {"text": "print('walltime='+r['walltime']+' budget_fits='+str(r['budget_fits']))\n"}, {"text": "PYRESULT\n"}], "path": "work/r2/native/supplied/o_build_D.sh", "sha256": "aba66dd23ce65301d9aed38ad348f50a3a3cd143be027250ba344958591015bc"}
